"""Editorial browser UI for the platform-wide test knowledge base."""

from __future__ import annotations

from .shared_header import SHARED_HEADER_CSS


def render_knowledge_html() -> str:
    return r"""<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Req2Test · Test Knowledge</title><style>
:root{--paper:#f3f4f2;--blue-paper:#eef2f5;--ink:#12171f;--muted:#68717d;--blue:#5f7fa8;--line:rgba(18,23,31,.11);--dark:#0f1823;--success:#307a5a;--danger:#a84f52;--display:Inter,-apple-system,BlinkMacSystemFont,"Helvetica Neue",Arial,sans-serif;--zh:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px var(--display);-webkit-font-smoothing:antialiased}a{color:inherit;text-decoration:none}button,input,select{font:inherit}.nav{position:sticky;top:18px;z-index:20;width:min(calc(100% - 36px),1400px);height:58px;margin:18px auto 0;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;padding:0 18px;border:1px solid rgba(255,255,255,.74);border-radius:16px;background:rgba(241,245,247,.82);box-shadow:0 14px 40px rgba(27,39,54,.08);backdrop-filter:blur(18px)}.brand{font-size:14px;font-weight:850;letter-spacing:.12em}.brand b{color:var(--blue)}.links{display:flex;gap:22px}.links a{position:relative;font-size:11px;font-weight:750;letter-spacing:.065em;white-space:nowrap}.links span{font-family:var(--zh);font-size:10px;color:var(--muted)}.links a.active:after{content:"";position:absolute;left:0;right:0;bottom:-8px;height:1px;background:var(--ink)}.account{justify-self:end;display:flex;gap:14px;align-items:center;font-size:11px}.account button{border:0;background:none;font-weight:750;cursor:pointer}main{width:min(calc(100% - 64px),1400px);margin:auto;padding:100px 0 120px}.hero{display:grid;grid-template-columns:1.2fr .8fr;align-items:end;gap:60px;padding-bottom:42px;border-bottom:1px solid rgba(18,23,31,.2)}.kicker,.label{font-size:10px;font-weight:800;letter-spacing:.17em;color:var(--muted)}h1{margin:18px 0 0;font-size:clamp(60px,7vw,100px);font-weight:500;line-height:.83;letter-spacing:-.06em}.hero p{justify-self:end;max-width:430px;margin:0;color:var(--muted);font:16px/1.75 var(--zh)}.summary{display:grid;grid-template-columns:1fr 1fr 1fr;margin:32px 0 62px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.fact{padding:22px 0;border-right:1px solid var(--line)}.fact:not(:first-child){padding-left:24px}.fact:last-child{border:0}.fact strong{display:block;font-size:30px;font-weight:520}.fact span{display:block;margin-top:9px;color:var(--muted);font-size:9px;letter-spacing:.1em}.section{display:grid;grid-template-columns:250px 1fr;gap:45px;padding:44px 0;border-top:1px solid var(--line)}.section h2{margin:8px 0;font-size:25px;letter-spacing:-.035em}.section small{font-family:var(--zh);color:var(--muted)}.search,.upload{display:grid;grid-template-columns:1fr 90px auto;gap:10px}.search input,.search select,.upload input,.upload select{min-width:0;padding:13px;border:1px solid var(--line);background:rgba(255,255,255,.45)}button.primary{padding:13px 18px;border:0;background:var(--dark);color:#fff;font-size:10px;font-weight:800;letter-spacing:.08em}.results{margin-top:24px}.result,.document{display:grid;grid-template-columns:minmax(220px,1.3fr) .65fr .65fr auto;gap:25px;align-items:center;padding:21px 0;border-bottom:1px solid var(--line)}.result{display:block}.result p{margin:10px 0;color:#48515d;line-height:1.7}.title{font-size:19px;font-weight:600}.meta,.state{color:var(--muted);font-size:10px;letter-spacing:.07em}.state.indexed{color:var(--success)}.state.failed{color:var(--danger)}.actions{display:flex;gap:8px}.actions button{padding:8px 10px;border:1px solid var(--line);background:transparent;font-size:9px;font-weight:800}.admin{display:none}.admin.visible{display:grid}.empty{padding:42px 0;color:var(--muted)}.error{margin-top:15px;color:var(--danger);font-size:12px}@media(max-width:1000px){.links{gap:10px}.links span{display:none}.section{grid-template-columns:1fr}}@media(max-width:760px){.links{display:none}main{width:calc(100% - 36px);padding-top:60px}.hero{grid-template-columns:1fr}.hero p{justify-self:start}.document{grid-template-columns:1fr auto}.document>*:nth-child(2),.document>*:nth-child(3){display:none}.search,.upload{grid-template-columns:1fr}.summary{grid-template-columns:1fr}}
__SHARED_HEADER_CSS__</style></head><body><header class="nav product-header"><a class="brand product-wordmark" href="/workbench">REQ<b>2</b>TEST</a><nav class="links product-nav"><a href="/workbench">工作台</a><a href="/tasks">测试任务</a><a class="active" href="/knowledge">知识库</a><a href="/workflow">工作流程</a><a href="/system">系统状态</a></nav><div class="account product-account"><a id="adminLink" style="display:none" href="/admin">管理</a><span id="account"></span><button onclick="logout()">退出</button></div></header><main><section class="hero"><div><div class="kicker">REQ2TEST / RAG EXPLAINABILITY</div><h1>TEST<br>KNOWLEDGE.</h1></div><p>平台级测试知识、索引状态与真实 RAG 召回预览。</p></section><div class="summary"><div class="fact"><strong id="total">—</strong><span>DOCUMENTS</span></div><div class="fact"><strong id="indexed">—</strong><span>INDEXED</span></div><div class="fact"><strong id="failed">—</strong><span>NEEDS ATTENTION</span></div></div><section class="section"><div><div class="label">检索预览</div><h2>RAG SEARCH<br><small>检索预览</small></h2></div><div><form class="search" onsubmit="search(event)"><input id="query" required maxlength="1000" placeholder="搜索测试规则"><select id="topK"><option>3</option><option selected>5</option><option>10</option></select><button class="primary">搜索 →</button></form><div class="results" id="results"></div></div></section><section class="section admin" id="adminUpload"><div><div class="label">上传文档</div><h2>UPLOAD<br><small>上传文档</small></h2></div><div><form class="upload" onsubmit="upload(event)"><input id="file" type="file" accept=".txt,.md,.docx,.pdf" required><select id="kind"><option value="testing_rule">测试规则</option><option value="historical_case">历史用例</option></select><button class="primary">建立索引 →</button></form><div class="error" id="uploadError"></div></div></section><section class="section"><div><div class="label">文档目录</div><h2>INDEXED<br>DOCUMENTS.<br><small>文档目录</small></h2></div><div id="documents"><div class="empty">正在加载</div></div></section></main><script>
let me=null;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const json=async r=>{try{return await r.json()}catch{return {detail:'Knowledge service unavailable'}}};async function af(url,o){const r=await fetch(url,o);if(r.status===401){location.replace('/login?next=/knowledge');throw Error('AUTH')}return r}async function boot(){const r=await af('/api/v1/auth/me');me=await json(r);account.textContent=me.email;if(me.role==='admin'){adminUpload.classList.add('visible');adminLink.style.display='block'}await load()}async function logout(){await fetch('/api/v1/auth/logout',{method:'POST'});location.replace('/login')}async function load(){const r=await af('/api/v1/knowledge/documents');const d=await json(r);total.textContent=d.total;indexed.textContent=d.items.filter(x=>x.index_status==='indexed').length;failed.textContent=d.items.filter(x=>x.index_status==='failed').length;documents.innerHTML=d.items.length?d.items.map(x=>`<article class="document"><div><div class="title">${esc(x.title)}</div><div class="meta">${esc(x.source_name)} · ${esc(x.id)}</div></div><div>${esc(x.kind)}</div><div class="state ${esc(x.index_status)}">${esc(x.index_status).toUpperCase()}</div><div class="actions">${me.role==='admin'?`<button onclick="reindex('${x.id}')">重新索引</button><button onclick="removeDoc('${x.id}')">删除</button>`:''}</div></article>`).join(''):'<div class="empty">暂无文档</div>'}async function search(e){e.preventDefault();const r=await af('/api/v1/knowledge/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:query.value,top_k:Number(topK.value)})}),d=await json(r);results.innerHTML=r.ok?(d.items.length?d.items.map(x=>`<article class="result"><div class="meta">${esc(x.source||'PLATFORM')} · ${esc(x.kind||'KNOWLEDGE')} · DISTANCE ${Number(x.distance??0).toFixed(4)}</div><p>${esc(x.text_excerpt)}</p></article>`).join(''):'<div class="empty">暂无召回</div>'):`<div class="error">${esc(d.detail)}</div>`}async function upload(e){e.preventDefault();uploadError.textContent='';const f=file.files[0];if(!f)return;const b64=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(',')[1]);r.onerror=no;r.readAsDataURL(f)}),r=await af('/api/v1/knowledge/documents',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:f.name,content_base64:b64,kind:kind.value})}),d=await json(r);if(!r.ok){uploadError.textContent=d.detail;return}file.value='';await load()}async function reindex(id){const r=await af(`/api/v1/knowledge/documents/${id}/reindex`,{method:'POST'});if(!r.ok)alert((await json(r)).detail);await load()}async function removeDoc(id){if(!confirm('删除 KNOWLEDGE DOCUMENT?'))return;const r=await af(`/api/v1/knowledge/documents/${id}`,{method:'DELETE'});if(!r.ok)alert((await json(r)).detail);await load()}boot();
</script></body></html>""".replace("__SHARED_HEADER_CSS__", SHARED_HEADER_CSS).replace(
        "</style></head>",
        "</style><style>.product-header{grid-template-columns:1fr auto 1fr}"
        ".links{justify-self:center}.account>span{max-width:180px;overflow:hidden;"
        "text-overflow:ellipsis;white-space:nowrap}.account button,.account a{white-space:nowrap}"
        ".document{grid-template-columns:minmax(220px,1.25fr) .55fr .75fr .45fr .7fr auto;gap:20px}"
        ".score-source{overflow:hidden;text-overflow:ellipsis}"
        "</style></head>",
    ).replace(
        "const json=async r=>",
        "const statusText=v=>({indexed:'已索引',indexing:'索引中',pending:'待索引',failed:'需处理'}[v]||v);"
        "const fmt=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—';const json=async r=>",
    ).replace(
        "failed.textContent=d.items.filter(x=>x.index_status==='failed').length;",
        "indexed.textContent=d.indexed;failed.textContent=d.needs_attention;",
    ).replace(
        '<div class="meta">${esc(x.source_name)} · ${esc(x.id)}</div></div><div>${esc(x.kind)}</div><div class="state ${esc(x.index_status)}">${esc(x.index_status).toUpperCase()}</div>',
        '<div class="meta">${esc(x.source_name)}</div></div><div>${esc(x.kind)}</div>'
        '<div class="source score-source">${esc(x.metadata?.source||x.source_name)}</div>'
        '<div>${esc(x.chunk_count)} 块</div><div class="updated">${esc(fmt(x.updated_at))}</div>'
        '<div class="state ${esc(x.index_status)}">${esc(statusText(x.index_status))}</div>',
    ).replace(
        "${esc(x.source||'PLATFORM')} · ${esc(x.kind||'KNOWLEDGE')} · DISTANCE ${Number(x.distance??0).toFixed(4)}",
        "${esc(x.source||'平台知识')} · ${esc(x.kind||'知识')} · 相似度 ${x.similarity==null?'—':Number(x.similarity).toFixed(3)} · CHUNK ${esc(x.chunk_index||'—')}",
    ).replace("删除 KNOWLEDGE DOCUMENT?", "删除知识文档？")
